    'Hi ha excepcions. Marxar per algun d’aquests motius sí que és situació legal de desocupació i, si compleixes la resta de requisits, dona dret a atur: un trasllat (art. 40 ET), una modificació substancial de les teves condicions que et perjudiqui (art. 41.3 ET), un incompliment greu de l’empresa, com ara no pagar-te o pagar-te tard una vegada i una altra (art. 50 ET), o la violència de gènere o sexual (art. 49.1.m ET). Ho recull l’art. 267.1.a.5.º LGSS. La sortida per l’art. 50 la sol declarar un jutjat.',
  'result.benefit_calculation':
    'La base és la mitjana del que s’ha cotitzat per desocupació en els últims 180 dies; aquí surt del teu salari brut anual amb les pagues extraordinàries, dividit entre 12, dins de les bases mínima i màxima del 2026. Es cobra el 70 % de la base els primers 180 dies i el 60 % després, amb un mínim i un màxim segons els fills o filles a càrrec teu. La durada segueix l’escala de l’art. 269.1: 360 dies cotitzats en els últims 6 anys donen 120 dies d’atur, i cada 180 més en sumen 60, fins a 720.',
