  'legal_notice.title': 'Avís legal · eslojusto.es',
  'legal_notice.description':
    'Qui hi ha darrere d’eslojusto.es i què fa i què no fa la seva revisió de la quitança. Informa sobre la llei i no fa assessorament jurídic.',
  'legal_notice.h1': 'Avís legal',
  'legal_notice.who': 'Qui hi ha darrere',
  'legal_notice.what_it_does': 'Què fa l’eina',
