  'legal_notice.owner':
    'eslojusto.es és un projecte personal. Aquestes són les dades del seu titular (art. 10 de la Ley de Servicios de la Sociedad de la Información):',
  'legal_notice.seller': 'El ven {titular}, amb NIF {nif}, titular d’eslojusto.es.',
