  'rent_indices.title': 'IRAV i IPC per al lloguer: {mes}',
  'rent_indices.description':
    'L’IRAV ({mes}) se situa en {irav} i l’IPC, en {ipc}. Cada mes des de novembre de 2024, amb el seu dia de publicació i l’enllaç a l’INE.',
  'rent_indices.h1': 'IRAV i IPC de cada mes',
  'rent_indices.lead':
    'Els índexs que marquen quant pot pujar el teu lloguer cada any, amb el dia en què l’INE va publicar cada xifra. L’IRAV surt cada mes juntament amb l’IPC definitiu.',
  'rent_indices.checked': 'Xifres comprovades en data {fecha}',
