    '4,99 € amb IVA inclòs. Un sol pagament, sense compte ni subscripció. El passi dura 7 dies i només val en aquest navegador: en aquest temps pots llegir fins a 15 paquets de documents, en qualsevol secció, i tornar a descarregar l’informe sense pagar una altra vegada. En un altre dispositiu, en una finestra privada o si esborres les dades de navegació, es perd.',
