    'Que l’interès mai no sigui negatiu no és una clàusula sòl: des del 16-06-2019, la llei exigeix que no ho sigui (art. 21.4).',
  'client.mortgage.calculation.flags.irph':
    'Segons el Tribunal de Justicia de la Unión Europea, el jutge examina cas per cas si l’IRPH es va explicar amb claredat; hi ha més preguntes pendents davant d’aquest tribunal. Depèn de cada cas i d’un jutge.',
  'client.mortgage.calculation.flags.default_interest_lcci':
    'Des del 16-06-2019, la llei fixa l’interès de demora: l’ordinari més 3 punts (art. 25).',
  'client.mortgage.calculation.flags.default_interest_lcci_differs':
    'La teva escriptura diu {default} amb un interès ordinari d’un {ordinary}: per llei seria {legal}.',
  'client.mortgage.calculation.flags.default_interest_lcci_matches':
    'La teva escriptura diu {default} amb un interès ordinari d’un {ordinary}: coincideix amb el que dona la llei ({legal}).',
  'client.mortgage.calculation.flags.default_interest_lh114':
    'Entre el 15-05-2013 i el 15-06-2019, en un préstec per comprar el teu habitatge habitual amb hipoteca sobre aquest habitatge, la llei limitava l’interès de demora a tres vegades l’interès legal del diner (art. 114 de la Ley Hipotecaria).',
  'client.mortgage.calculation.flags.default_interest_lh114_above':
    'La teva escriptura diu {default}: més de tres vegades l’interès legal més alt d’aquells anys ({limit}).',
  'client.mortgage.calculation.flags.default_interest_lh114_earlier':
    'La teva escriptura és anterior al 15-05-2013. La Ley 1/2013 aplica el límit de l’art. 114 de la Ley Hipotecaria, tres vegades l’interès legal del diner, als interessos de demora dels préstecs amb hipoteca sobre habitatge habitual constituïts abans d’aquesta data: als que es meritin des d’aleshores i als ja meritats que no s’haguessin pagat (disposició transitòria segona). Aquí no es dona xifra.',
  'client.mortgage.calculation.flags.default_interest_case_law':
    'Per a les escriptures anteriors al 16-06-2019 amb consumidors, el Tribunal Supremo pren com a referència l’interès ordinari més 2 punts per valorar el de demora, i el Tribunal de Justicia de la Unión Europea diu que aquest criteri no és contrari al dret europeu. Depèn d’un jutge.',
  'client.mortgage.calculation.flags.default_interest_case_law_above':
    'La teva escriptura diu {default} amb un interès ordinari d’un {ordinary}: més que aquesta referència ({reference}).',
  'client.mortgage.calculation.flags.early_termination':
    'La llei fixa el mínim que s’ha de deure perquè el banc pugui demanar tot el préstec: en la primera meitat del termini, el 3 % del capital o 12 quotes mensuals; en la segona, el 7 % o 15 quotes; i abans, un mes d’avís per pagar (art. 24).',
  'client.mortgage.calculation.flags.early_termination_earlier_deed':
    'A les escriptures anteriors al 16-06-2019 se’ls apliquen avui aquests mínims, llevat que la seva clàusula sigui més favorable per a tu (disposició transitòria primera, 4).',
  'client.mortgage.calculation.flags.early_termination_fewer':
    'Quotes impagades que demana la teva escriptura: {instalments}, menys de les que fixa la llei.',
  'client.mortgage.calculation.flags.early_termination_case_law':
    'Sobre les clàusules de venciment anticipat d’escriptures anteriors al 2019 hi ha criteri del Tribunal de Justicia de la Unión Europea; com s’aplica a la teva depèn d’un jutge.',
  'client.mortgage.calculation.flags.rounding_up':
    'Un arrodoniment que només va a l’alça sempre afavoreix el banc. La llei de consumidors s’ocupa dels arrodoniments a l’alça (art. 87.5 del text refós de la Ley General para la Defensa de los Consumidores y Usuarios); aquí no es valora la teva clàusula.',
  'client.mortgage.calculation.flags.opening_fee_amount':
    'La teva escriptura fixa una comissió d’obertura: {fee}.',
  'client.mortgage.calculation.flags.opening_fee_share': 'És un {share} del capital del préstec.',
  'client.mortgage.calculation.flags.opening_fee_duplicate':
    'Des del 16-06-2019, la llei no permet cobrar a part per serveis que ja cobreix la comissió d’obertura, com l’estudi o la tramitació (art. 14.4).',
  'client.mortgage.calculation.flags.opening_fee_case_law':
    'Sobre la comissió d’obertura, el Tribunal de Justicia de la Unión Europea diu que el jutge examina cas per cas si es va explicar amb claredat; depèn d’un jutge.',
  'client.mortgage.calculation.flags.insurance_tied':
    'La llei regula quan el banc et pot demanar una assegurança o un altre producte per donar-te el préstec i et deixa contractar aquesta assegurança amb una altra entitat (art. 17).',
  'client.mortgage.calculation.flags.insurance_before_lcci':
    'La teva escriptura és anterior al 16-06-2019, quan la llei va començar a prohibir les vendes vinculades (art. 17). Des del 2012, l’Orden EHA/2899/2011 obligava a informar de si cada servei vinculat es podia contractar per separat i en quines condicions (art. 12): aquí no es valora.',
  'client.mortgage.calculation.information.fein_timing':
    'Des del 16-06-2019, el banc et lliura la fitxa europea d’informació normalitzada (FEIN) i la fitxa d’advertiments (FiAE) almenys 10 dies naturals abans de l’escriptura (arts. 14 i 15).',
  'client.mortgage.calculation.information.transparency_act':
    'Com a molt tard el dia abans de l’escriptura, el notari t’assessora i ho deixa en una acta que no se’t cobra, i l’escriptura ho menciona (art. 15).',
  'client.mortgage.calculation.information.handwritten_statement':
    'Entre el 15-05-2013 i el 15-06-2019, si vas demanar la hipoteca com a persona física, sobre un habitatge o per comprar o conservar un terreny o un edifici, i tenia límits a la variació del tipus, com un sòl i un sostre, «en los cuales el límite de variabilidad a la baja sea inferior al límite de variabilidad al alza», un instrument de cobertura del risc de tipus d’interès o es concedia en divises, l’escriptura havia de portar una expressió escrita a mà en què constava que t’havien advertit dels seus riscos (art. 6 de la Ley 1/2013).',
  'client.mortgage.calculation.information.limitation_rule':
    'Segons el Tribunal de Justicia de la Unión Europea, el termini per demanar el que s’ha pagat per una clàusula de despeses pot començar a comptar quan és ferma la sentència que l’anul·la, llevat que el banc provi que ja es podia saber abans que la clàusula no era vàlida (C-561/21). És el criteri, no un càlcul del teu cas.',
  'client.mortgage.calculation.information.prior_step_439bis':
    'Des del 03-04-2025, la llei regula un pas previ concret abans d’anar a un jutjat per clàusules d’una hipoteca (art. 439 bis de la Ley de Enjuiciamiento Civil). A l’enllaç tens el text de la llei.',
  'client.mortgage.calculation.information.loan_assignment':
    'Des del 08-10-2026, el Real Decreto-ley 29/2026 afegeix a la llei un art. 25 bis: si el banc cedeix el teu préstec a un altre, conserves davant del nou titular el que podies oposar al banc, i se t’ha d’informar de la cessió llevat que el banc, d’acord amb el nou titular, continuï prestant els serveis del préstec (art. 25 bis.3). Està pendent de convalidació.',
  'client.mortgage.calculation.information.complaints_service':
    'El Servicio de Reclamaciones del Banco de España atén consultes i queixes sobre bancs (art. 30 de la Ley 44/2002), i les oficines públiques de consum informen gratis.',
