    'En una compra finançada, el contracte ha de dir el bé i el seu preu al comptat (art. 16.2).',
  'client.credit.calculation.information.linked_credit':
    'Si el préstec serveix només per pagar la compra d’un bé o un servei concrets i forma una unitat amb aquesta compra, és un crèdit vinculat (art. 29.1). Aleshores el contracte ha de dir el bé i el seu preu al comptat (art. 16.2.e); si desisteixes de la compra, el préstec deixa d’obligar-te sense penalització (art. 29.2); i si el bé no arriba o no és conforme, en alguns casos aquests drets valen també davant del prestador (art. 29.3).',
  'client.credit.calculation.information.cash_option':
    'I pots no finançar la compra i pagar-la com vas acordar amb el venedor (art. 26.3).',
  'client.credit.calculation.information.revolving_info':
    'L’ordre de transparència bancària preveu que una targeta revolving informi almenys cada trimestre del que es deu, el tipus, la quota i quan i per quant acabaries de pagar-la (art. 33 quinquies), i que, si ho demanes, et donin en 5 dies hàbils el que s’ha pagat i el que es deu, amb el seu desglossament, i un quadre d’amortització (art. 33 sexies). No s’ha comprovat a quines entitats i contractes anteriors arriba, així que no s’afirma que la teva hi estigui obligada.',
